# midterm bands are not in exhibits.json bands -> computed here from the cohort file, same rule as the pack
import pandas as pd
A = pd.read_csv(f'{HERE}/cohort_last_full.csv'); m = A.midterm.fillna(-1)
mb = [('απουσία', m < 0), ('κάτω από 5', (m >= 0) & (m < 5)), ('5 έως 6,5', (m >= 5) & (m < 7)), ('7 και άνω', m >= 7)]
MID = [dict(l=l, v=round(float(A[f].passed.mean()), 4), n=int(f.sum())) for l, f in mb]
json.dump(MID, open(f'{HERE}/midterm_bands.json', 'w', encoding='utf8'), ensure_ascii=False)
